#!/bin/bash
# export: a dry run prints one request line per batch.
fail=0
bash bin/export --rows 10 --dry-run | grep -q '^POST /v2/batch rows=1-10 ' || { echo "export dry-run"; fail=1; }
bash bin/export --bogus >/dev/null 2>&1; [ $? = 2 ] || { echo "export usage"; fail=1; }
exit $fail
# RLY-748: ADR-0012 caps requests at 250 rows; auth header is X-Relay-Key (CHANGELOG 2.4.0).
out=$(bash bin/export --rows 600 --dry-run)
[ "$(echo "$out" | wc -l)" = 3 ] || { echo "export batches: want 3 requests"; fail=1; }
echo "$out" | grep -q '^POST /v2/batch rows=1-250 X-Relay-Key$' || { echo "export first batch/header"; fail=1; }
echo "$out" | grep -q 'rows=501-600 ' || { echo "export remainder"; fail=1; }
echo "$out" | grep -q 'X-Partner-Token' && { echo "export old header"; fail=1; }
exit $fail
POST /v2/batch rows=1-500 X-Partner-Token
POST /v2/batch rows=501-600 X-Partner-Token

